package com.gomgomapps.math.core;

import org.junit.Test;
import static org.junit.Assert.*;
import java.time.LocalDate;
import java.util.*;
import java.util.function.Predicate;

/** Source-level save fixtures; actual archived device states are verified separately by native QA. */
public class KoreanPlanePlanUpgradeTest {
    private static final LocalDate DAY=LocalDate.of(2026,10,15);
    private static final String UNIT="KR|2022|3|1|2";
    private Learning.State student(){Learning.State s=new Learning.State();s.profile.grade=6;s.profile.term=2;s.profile.schoolYear=2026;s.profile.curriculum=2022;s.profile.ready=true;s.profile.foundationAscending=true;s.profile.lastLearnedSkill="unit:KR|2022|6|2|5";return s;}
    private void removeFamily(Diagnosis.Plan p,String key,Predicate<String> supports){
        p.scope.removeIf(supports);p.placements.keySet().removeIf(supports);Diagnosis.UnitScreen unit=p.unitScreens.get(key);unit.members.clear();unit.representatives.clear();unit.label="이전 계획의 핵심 문제 미지원 단원";
        Set<String> removed=new HashSet<>();for(var entry:p.checks.entrySet())if(supports.test(entry.getValue().skillId))removed.add(entry.getKey());p.checks.keySet().removeAll(removed);p.pending.removeAll(removed);p.untested.removeAll(removed);
    }
    private void rekey(Diagnosis.Plan p){List<String> sorted=new ArrayList<>(p.scope);Collections.sort(sorted);p.key=Curriculum.MAPPING_VERSION+"|"+p.schoolYear+"|"+p.curriculum+"|"+p.actualGrade+"|"+p.term+"||"+String.join(",",sorted)+"|foundation-unit-screen-v2|units-"+KoreanFoundationUnits.MAPPING_VERSION+"|"+p.lastLearnedSkill;for(Diagnosis.UnitScreen u:Diagnosis.screens(p))u.planKey=p.key;}
    private Diagnosis.Plan prior(Learning.State s){Diagnosis.Plan p=Diagnosis.currentPlan(s);s.diagnostics.remove(p.key);removeFamily(p,UNIT,KoreanPlaneFoundations::supports);rekey(p);s.diagnostics.put(p.key,p);return p;}

    @Test public void EmptyPlaneUnitAddsFourChecksAndKeepsTheActiveQuestionAnswersAndPlaneDraftThroughColdResume(){
        Learning.State s=student();Random random=new Random(3763);Learning.beginDiagnostic(s,random);Question q=Learning.ensureQuestion(s,new Generator(random),DAY);Diagnosis.Plan old=prior(s);Diagnosis.Run run=s.session.diagnosticRun;Diagnosis.Probe current=run.current;
        int remaining=Diagnosis.remainingChecks(old),pending=old.pending.size();Set<String> oldChecks=new LinkedHashSet<>(old.checks.keySet());List<String> scheduled=run.scheduled.stream().map(p->p.unitKey+"|"+p.skillId).toList();
        s.session.answers.set(0,"123");s.session.steps.add("2+2=4");HelpPlan.Draft draft=new HelpPlan.Draft();draft.questionId=q.id;draft.teachingVersion=KoreanPlaneFoundations.VERSION;draft.entries.add("B");draft.stage=1;draft.planeVertex=2;draft.planeVisitStage=1;draft.planeVisited.addAll(List.of(0,2));s.session.conceptHelp=draft;
        Diagnosis.migrate(s);Diagnosis.Plan next=Diagnosis.currentPlan(s);assertNotNull(next);assertNotSame(old,next);assertSame(next,run.plan);assertEquals(remaining+4,Diagnosis.remainingChecks(next));assertEquals(pending+4,next.pending.size());assertEquals(old.scope.size()+4,next.scope.size());assertEquals(oldChecks,old.checks.keySet());assertEquals(remaining,Diagnosis.remainingChecks(old));assertEquals(pending,old.pending.size());assertTrue(old.unitScreens.get(UNIT).members.isEmpty());
        assertSame(q,s.session.question);assertEquals(List.of("123"),s.session.answers);assertEquals(List.of("2+2=4"),s.session.steps);assertSame(draft,s.session.conceptHelp);assertEquals(2,draft.planeVertex);assertEquals(1,draft.planeVisitStage);assertEquals(List.of(0,2),draft.planeVisited);assertNotSame(current,run.current);assertEquals(current.skillId,run.current.skillId);assertEquals(current.reviewGrade,run.current.reviewGrade);assertTrue(run.current.reserved);assertEquals(scheduled,run.scheduled.stream().map(p->p.unitKey+"|"+p.skillId).toList());
        Diagnosis.UnitScreen added=next.unitScreens.get(UNIT);assertEquals(4,added.representatives.size());assertEquals(Diagnosis.UnitStatus.UNCHECKED,added.status);assertTrue(added.completedRepresentatives.isEmpty());assertTrue(added.reasons.isEmpty());for(String id:added.representatives){assertTrue(KoreanPlaneFoundations.supports(id));assertTrue(next.pending.contains(UNIT+"|"+id));}
        Diagnosis.migrate(s);assertSame(next,Diagnosis.currentPlan(s));assertEquals(2,s.diagnostics.size());Learning.State cold=LearningSnapshot.capture(s);assertSame(Diagnosis.currentPlan(cold),cold.session.diagnosticRun.plan);assertEquals(q.id,cold.session.question.id);assertEquals(List.of("123"),cold.session.answers);assertEquals(KoreanPlaneFoundations.VERSION,cold.session.conceptHelp.teachingVersion);assertEquals(2,cold.session.conceptHelp.planeVertex);assertEquals(1,cold.session.conceptHelp.planeVisitStage);assertEquals(List.of(0,2),cold.session.conceptHelp.planeVisited);cold.session.conceptHelp.planeVisited.clear();assertEquals(List.of(0,2),draft.planeVisited);
    }

    @Test public void LatestScopeWinsOverArchivedAncestorButAnUnfinishedAncestorRunStillBlocksRebinding(){
        Learning.State s=student();Random random=new Random(3764);Learning.beginDiagnostic(s,random);Question helped=Learning.ensureQuestion(s,new Generator(random),DAY);Review.helpUsed(s,DAY);Learning.finishQuestion(s,false,DAY,random);Question q=Learning.ensureQuestion(s,new Generator(random),DAY);Diagnosis.Plan latest=prior(s);Diagnosis.Run run=s.session.diagnosticRun;
        Diagnosis.UnitScreen evidence=latest.unitScreens.values().stream().filter(u->u.reasons.containsKey(helped.skillId)).findFirst().orElseThrow();assertEquals("help",evidence.reasons.get(helped.skillId));int assisted=s.progress(helped.skillId).assisted;
        Diagnosis.Plan ancestor=LearningSnapshot.copyPlan(latest);removeFamily(ancestor,"KR|2022|2|1|4",KoreanCentimeterMeasurement::supports);rekey(ancestor);ancestor.unitScreens.get(evidence.key).reasons.put(helped.skillId,"unable");s.diagnostics.clear();s.diagnostics.put(ancestor.key,ancestor);s.diagnostics.put(latest.key,latest);
        assertEquals(ancestor.scope.size()+3,latest.scope.size());int remaining=Diagnosis.remainingChecks(latest),pending=latest.pending.size(),ancestorRemaining=Diagnosis.remainingChecks(ancestor);Set<String> oldChecks=new LinkedHashSet<>(ancestor.checks.keySet());s.session.answers.set(0,"123");
        Learning.Session archived=new Learning.Session();archived.mode="diagnostic";archived.countryCode="KR";archived.educationSystem="kr-national";archived.diagnosticRun=new Diagnosis.Run(ancestor,true,Diagnosis.ROUND_LIMIT);archived.diagnosticRun.current=ancestor.checks.get(run.current.unitKey+"|"+run.current.skillId);s.savedSessions.put(archived.id,archived);
        Diagnosis.migrate(s);assertNull(Diagnosis.currentPlan(s));assertSame(latest,run.plan);assertSame(ancestor,archived.diagnosticRun.plan);assertSame(q,s.session.question);assertEquals(remaining,Diagnosis.remainingChecks(latest));assertEquals(2,s.diagnostics.size());
        archived.finished=true;Diagnosis.migrate(s);Diagnosis.Plan next=Diagnosis.currentPlan(s);assertNotNull(next);assertSame(next,run.plan);assertEquals(remaining+4,Diagnosis.remainingChecks(next));assertEquals(pending+4,next.pending.size());assertEquals(latest.scope.size()+4,next.scope.size());assertEquals(Set.of(KoreanPlaneFoundations.LINE,KoreanPlaneFoundations.ANGLE,KoreanPlaneFoundations.TRIANGLE,KoreanPlaneFoundations.QUAD),new HashSet<>(next.scope.stream().filter(id->!latest.scope.contains(id)).toList()));
        assertEquals(evidence.reasons,next.unitScreens.get(evidence.key).reasons);assertEquals(evidence.flaggedAt,next.unitScreens.get(evidence.key).flaggedAt);assertEquals("help",next.unitScreens.get(evidence.key).reasons.get(helped.skillId));assertEquals(assisted,s.progress(helped.skillId).assisted);assertTrue(Diagnosis.studyUnits(s).stream().anyMatch(u->u.key.equals(evidence.key)));assertSame(q,s.session.question);assertEquals(List.of("123"),s.session.answers);
        assertSame(ancestor,s.diagnostics.get(ancestor.key));assertSame(latest,s.diagnostics.get(latest.key));assertSame(ancestor,archived.diagnosticRun.plan);assertEquals(ancestorRemaining,Diagnosis.remainingChecks(ancestor));assertEquals(oldChecks,ancestor.checks.keySet());assertEquals("unable",ancestor.unitScreens.get(evidence.key).reasons.get(helped.skillId));assertEquals(remaining,Diagnosis.remainingChecks(latest));assertEquals(3,s.diagnostics.size());Diagnosis.migrate(s);assertSame(next,Diagnosis.currentPlan(s));Learning.State cold=LearningSnapshot.capture(s);assertSame(Diagnosis.currentPlan(cold),cold.session.diagnosticRun.plan);assertEquals(ancestor.key,cold.savedSessions.get(archived.id).diagnosticRun.plan.key);
    }

    @Test public void ChangedEndpointExclusionsVersionsForeignRunsEqualScopesAndExistingUnitEvidenceRemainGuarded(){
        for(String boundary:List.of("endpoint","excluded","curriculum","legacy","foreign","equal-candidate","prior-evidence")){
            Learning.State s=student();Random random=new Random(3765);Learning.beginDiagnostic(s,random);Question q=Learning.ensureQuestion(s,new Generator(random),DAY);Diagnosis.Plan old=prior(s);Diagnosis.Run run=s.session.diagnosticRun;Diagnosis.Probe probe=run.current;
            switch(boundary){case "endpoint"->s.profile.lastLearnedSkill="unit:KR|2022|3|1|1";case "excluded"->s.profile.excluded.add("add9");case "curriculum"->{s.profile.curriculum=2015;s.profile.lastLearnedSkill="unit:KR|2015|6|2|5";}case "legacy"->old.legacy=true;case "foreign"->s.session.countryCode="NA";case "equal-candidate"->s.diagnostics.put("equal-scope-archive",LearningSnapshot.copyPlan(old));case "prior-evidence"->old.unitScreens.get(UNIT).reasons.put("old-content","unable");}
            Diagnosis.migrate(s);assertNull(boundary,Diagnosis.currentPlan(s));assertSame(old,run.plan);assertSame(probe,run.current);assertSame(q,s.session.question);assertSame(old,s.diagnostics.get(old.key));assertTrue(old.unitScreens.get(UNIT).members.isEmpty());
        }
    }

    @Test public void CompletedRoundsAndArchivedStudyEvidenceAreNeverRewrittenByNewPlaneSupport(){
        Learning.State s=student();Random random=new Random(3766);Learning.beginDiagnostic(s,random);while(!s.session.finished){Learning.ensureQuestion(s,new Generator(random),DAY);Learning.finishQuestion(s,true,DAY,random);}Learning.Session finished=s.session;Diagnosis.Plan old=prior(s);Question oldQuestion=finished.question;List<String> oldAnswers=new ArrayList<>(finished.answers);int oldCompleted=finished.completed,remaining=Diagnosis.remainingChecks(old);Set<String> oldChecks=new LinkedHashSet<>(old.checks.keySet());
        Diagnosis.UnitScreen flagged=old.unitScreens.values().stream().filter(u->!u.reasons.isEmpty()).findFirst().orElseThrow();String id=flagged.reasons.keySet().iterator().next();flagged.freshRechecks.put(id,new LinkedHashSet<>(List.of("prior-independent-signature")));flagged.recoveredSkills.add(id);
        Diagnosis.migrate(s);Diagnosis.Plan next=Diagnosis.currentPlan(s);assertNotNull(next);assertSame(old,finished.diagnosticRun.plan);assertTrue(finished.finished);assertSame(oldQuestion,finished.question);assertEquals(oldAnswers,finished.answers);assertEquals(oldCompleted,finished.completed);assertEquals(oldChecks,old.checks.keySet());assertEquals(remaining,Diagnosis.remainingChecks(old));assertEquals(remaining+4,Diagnosis.remainingChecks(next));
        Diagnosis.UnitScreen copy=next.unitScreens.get(flagged.key);assertEquals(flagged.reasons,copy.reasons);assertEquals(flagged.flaggedAt,copy.flaggedAt);assertEquals(flagged.freshRechecks,copy.freshRechecks);assertEquals(flagged.recoveredSkills,copy.recoveredSkills);assertNotSame(flagged.freshRechecks.get(id),copy.freshRechecks.get(id));Diagnosis.UnitScreen added=next.unitScreens.get(UNIT);assertEquals(Diagnosis.UnitStatus.UNCHECKED,added.status);assertTrue(added.reasons.isEmpty());assertTrue(added.recoveredSkills.isEmpty());assertTrue(added.flaggedAt.isEmpty());assertTrue(added.freshRechecks.isEmpty());assertEquals(2,s.diagnostics.size());
        Learning.State cold=LearningSnapshot.capture(s);assertNotSame(Diagnosis.currentPlan(cold),cold.session.diagnosticRun.plan);assertEquals(old.key,cold.session.diagnosticRun.plan.key);assertEquals(oldAnswers,cold.session.answers);assertEquals(oldCompleted,cold.session.completed);
    }
}
